[ExtensionOf(tableStr(smmBusRelChainGroup))]
final class AVAsmmBusRelChainGroupDbt_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "_chainId">smmChainId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>smmBusRelChainGroup</returns>
public static smmBusRelChainGroup avaFindChainId(smmChainId _chainId
    , boolean _forUpdate = false)
{
    smmBusRelChainGroup avaChainGroup;

    if(_chainId)
    {
        if(_forUpdate)
        {
            avaChainGroup.selectForUpdate(_forUpdate);
        }

        avaChainGroup.selectLocked(_forUpdate);

        select firstonly avaChainGroup
            where avaChainGroup.ChainId == _chainId;
    }

    return avaChainGroup;
}
